SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
CREATE SCHEMA mistri;
CREATE FUNCTION mistri.analytics_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND current_setting('mistri.analytics_prune', true) = 'on' THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Analytics events are append-only; retention goes through prune.';
END $$;
SET default_tablespace = '';
SET default_table_access_method = heap;
CREATE TABLE mistri.analytics_events (
    id bigint NOT NULL,
    occurred_at bigint NOT NULL,
    received_at bigint NOT NULL,
    environment text NOT NULL COLLATE pg_catalog."C",
    tenant_id text COLLATE pg_catalog."C",
    kind text NOT NULL COLLATE pg_catalog."C",
    name text NOT NULL COLLATE pg_catalog."C",
    step text COLLATE pg_catalog."C",
    unit_kind text COLLATE pg_catalog."C",
    unit_id text COLLATE pg_catalog."C",
    fields jsonb NOT NULL,
    source_event_id text COLLATE pg_catalog."C",
    CONSTRAINT analytics_events_check CHECK (((unit_kind IS NULL) = (unit_id IS NULL))),
    CONSTRAINT analytics_events_environment_check CHECK (((octet_length(environment) >= 1) AND (octet_length(environment) <= 128))),
    CONSTRAINT analytics_events_fields_check CHECK (((jsonb_typeof(fields) = 'object'::text) AND (octet_length((fields)::text) <= 4096))),
    CONSTRAINT analytics_events_kind_check CHECK ((kind = ANY (ARRAY['view'::text, 'action'::text, 'form'::text, 'event'::text, 'business'::text]))),
    CONSTRAINT analytics_events_name_check CHECK (((octet_length(name) >= 1) AND (octet_length(name) <= 128))),
    CONSTRAINT analytics_events_occurred_at_check CHECK (((occurred_at >= 0) AND (occurred_at <= '9007199254740991'::bigint))),
    CONSTRAINT analytics_events_received_at_check CHECK (((received_at >= 0) AND (received_at <= '9007199254740991'::bigint))),
    CONSTRAINT analytics_events_source_event_id_check CHECK (((source_event_id IS NULL) OR ((octet_length(source_event_id) >= 1) AND (octet_length(source_event_id) <= 128)))),
    CONSTRAINT analytics_events_step_check CHECK (((step IS NULL) OR ((octet_length(step) >= 1) AND (octet_length(step) <= 128)))),
    CONSTRAINT analytics_events_tenant_id_check CHECK (((tenant_id IS NULL) OR ((octet_length(tenant_id) >= 1) AND (octet_length(tenant_id) <= 128)))),
    CONSTRAINT analytics_events_unit_id_check CHECK (((unit_id IS NULL) OR ((octet_length(unit_id) >= 1) AND (octet_length(unit_id) <= 128)))),
    CONSTRAINT analytics_events_unit_kind_check CHECK (((unit_kind IS NULL) OR (unit_kind = ANY (ARRAY['subject'::text, 'visitor'::text]))))
);
CREATE SEQUENCE mistri.analytics_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE mistri.analytics_events_id_seq OWNED BY mistri.analytics_events.id;
CREATE TABLE mistri.analytics_meta (
    singleton integer NOT NULL,
    version integer NOT NULL,
    app_id text NOT NULL COLLATE pg_catalog."C",
    deployment_id text NOT NULL COLLATE pg_catalog."C",
    CONSTRAINT analytics_meta_app_id_check CHECK (((octet_length(app_id) >= 1) AND (octet_length(app_id) <= 128))),
    CONSTRAINT analytics_meta_deployment_id_check CHECK (((octet_length(deployment_id) >= 1) AND (octet_length(deployment_id) <= 128))),
    CONSTRAINT analytics_meta_singleton_check CHECK ((singleton = 1)),
    CONSTRAINT analytics_meta_version_check CHECK ((version = 1))
);
CREATE TABLE mistri.analytics_sink_cursors (
    sink_id text NOT NULL COLLATE pg_catalog."C",
    after_id bigint NOT NULL,
    updated_at bigint NOT NULL,
    CONSTRAINT analytics_sink_cursors_after_id_check CHECK ((after_id >= 0)),
    CONSTRAINT analytics_sink_cursors_sink_id_check CHECK (((octet_length(sink_id) >= 1) AND (octet_length(sink_id) <= 128))),
    CONSTRAINT analytics_sink_cursors_updated_at_check CHECK (((updated_at >= 0) AND (updated_at <= '9007199254740991'::bigint)))
);
ALTER TABLE ONLY mistri.analytics_events ALTER COLUMN id SET DEFAULT nextval('mistri.analytics_events_id_seq'::regclass);
INSERT INTO mistri.analytics_meta (singleton, version, app_id, deployment_id) VALUES (1, 1, 'layout', 'layout-deployment');
SELECT pg_catalog.setval('mistri.analytics_events_id_seq', 1, false);
ALTER TABLE ONLY mistri.analytics_events
    ADD CONSTRAINT analytics_events_pkey PRIMARY KEY (id);
ALTER TABLE ONLY mistri.analytics_events
    ADD CONSTRAINT analytics_events_source_event_id_key UNIQUE (source_event_id);
ALTER TABLE ONLY mistri.analytics_meta
    ADD CONSTRAINT analytics_meta_pkey PRIMARY KEY (singleton);
ALTER TABLE ONLY mistri.analytics_sink_cursors
    ADD CONSTRAINT analytics_sink_cursors_pkey PRIMARY KEY (sink_id);
CREATE INDEX analytics_events_name_unit ON mistri.analytics_events USING btree (name, unit_id, occurred_at);
CREATE INDEX analytics_events_occurred_at ON mistri.analytics_events USING brin (occurred_at);
CREATE TRIGGER analytics_events_append_only BEFORE DELETE OR UPDATE ON mistri.analytics_events FOR EACH ROW EXECUTE FUNCTION mistri.analytics_append_only();
CREATE TRIGGER analytics_events_no_truncate BEFORE TRUNCATE ON mistri.analytics_events FOR EACH STATEMENT EXECUTE FUNCTION mistri.analytics_append_only();
